class Termometro:
    def __init__(self, celsius=0):
        self._celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, valor):
        if valor < -273.15:
            raise ValueError("Temperatura imposible")
        self._celsius = valor

    @property
    def fahrenheit(self):
        return (self._celsius * 9/5) + 32

class Producto:
    def __init__(self, nombre, precio_base):
        self.nombre = nombre
        self._precio_base = precio_base
        self._descuento = 0

    @property
    def precio(self):
        return self._precio_base * (1 - self._descuento / 100)

    def aplicar_descuento(self, porcentaje):
        if 0 <= porcentaje <= 100:
            self._descuento = porcentaje
        else:
            raise ValueError("Descuento inválido")

class CuentaBancaria:
    def __init__(self, titular, saldo_inicial=0):
        self.titular = titular
        self._saldo = max(0, saldo_inicial)

    @property
    def saldo(self):
        return self._saldo

    def depositar(self, monto):
        if monto > 0:
            self._saldo += monto

    def retirar(self, monto):
        if monto > 0 and monto <= self._saldo:
            self._saldo -= monto
            return True
        return False

