class Rectangulo:
    def __init__(self, base, altura):
        self.base = base
        self.altura = altura

    @property
    def area(self):
        return self.base * self.altura

    @property
    def perimetro(self):
        return 2 * (self.base + self.altura)

r = Rectangulo(5, 3)
print(r.area)        # 15
print(r.perimetro)   # 16

class Triangulo:
    def __init__(self, lado1, lado2, lado3):
        self.lado1 = lado1
        self.lado2 = lado2
        self.lado3 = lado3

    def _validar_triángulo(self):
        a, b, c = self.lado1, self.lado2, self.lado3
        return a + b > c and a + c > b and b + c > a

    @property
    def lado1(self):
        return self._lado1

    @lado1.setter
    def lado1(self, valor):
        self._lado1 = valor
        if not self._validar_triángulo():
            raise ValueError("No forma triángulo válido")

class Archivo:
    def __init__(self, nombre):
        self._nombre = nombre
        self._contenido = ""

