class Estudiante:
    def __init__(self, nombre):
        self.nombre = nombre
        self._notas = []

    def agregar_nota(self, nota):
        if 0 <= nota <= 100:
            self._notas.append(nota)
        else:
            raise ValueError("Nota inválida")

    @property
    def promedio(self):
        if not self._notas:
            return 0
        return sum(self._notas) / len(self._notas)

